function countOccurrences(text, searchString) {
    // Convert both text and searchString to lowercase to make the search case-insensitive
    const lowerCaseText = text.toLowerCase();
    const lowerCaseSearchString = searchString.toLowerCase();

    // Use the split method to divide the text by the search string
    const parts = lowerCaseText.split(lowerCaseSearchString);

    // The number of occurrences is the length of the parts array minus one
    return parts.length - 1;
}

