class MainActivity : AppCompatActivity() {
    private lateinit var shapeTypeSpinner: Spinner
    private lateinit var dimension1EditText: EditText
    private lateinit var dimension2EditText: EditText
    private lateinit var calculateButton: Button
    private lateinit var resultTextView: TextView
    private val shapeFactory = ShapeFactory()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        shapeTypeSpinner = findViewById(R.id.shapeTypeSpinner)
        dimension1EditText = findViewById(R.id.dimension1EditText)
        dimension2EditText = findViewById(R.id.dimension2EditText)
        calculateButton = findViewById(R.id.calculateButton)
        resultTextView = findViewById(R.id.resultTextView)

        val shapes = listOf("Circle", "Rectangle", "Triangle")
        val adapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, shapes)
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)

        shapeTypeSpinner.adapter = adapter

        shapeTypeSpinner.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onNothingSelected(parent: AdapterView<*>) {}

            override fun onItemSelected(parent: AdapterView<*>, view: View?, position: Int, id: Long) {
                when (shapes[position]) {
                    "Circle" -> {
                        dimension1EditText.hint = "Radius"
                        dimension2EditText.visibility = View.GONE
                    }
                    "Rectangle" -> {
                        dimension1EditText.hint = "Width"
                        dimension2EditText.hint = "Height"
                        dimension2EditText.visibility = View.VISIBLE
                    }
                    "Triangle" -> {
                        dimension1EditText.hint = "Base"
                        dimension2EditText.hint = "Height"
                        dimension2EditText.visibility = View.VISIBLE
                    }
                }
            }
        }

        calculateButton.setOnClickListener {
            val shapeType = shapeTypeSpinner.selectedItem.toString()
            val dimension1 = dimension1EditText.text.toString().toDoubleOrNull()
            val dimension2 = dimension2EditText.text.toString().toDoubleOrNull()

            if (dimension1 == null || (dimension2EditText.visibility == View.VISIBLE && dimension2 == null)) {
                resultTextView.text = "Please enter valid dimensions"
                return@setOnClickListener
            }

            val shape: Shape? = if (dimension2EditText.visibility == View.VISIBLE) {
                shapeFactory.createShape(shapeType, dimension1, dimension2!!)
            } else {
                shapeFactory.createShape(shapeType, dimension1)
            }

            shape?.let {
                resultTextView.text = "Area: ${it.area()}"
            }
        }
    }
}
