document.addEventListener("DOMContentLoaded", function() {
    // Function to generate Fibonacci sequence up to n terms
    function generateFibonacci(n) {
        if (n <= 0) return [];

        const sequence = [0];
        if (n === 1) return sequence;

        sequence.push(1);
        for (let i = 2; i < n; i++) {
            sequence.push(sequence[i - 1] + sequence[i - 2]);
        }
        return sequence;
    }

    // Function to display the Fibonacci sequence within an HTML element
    function displayFibonacci(sequence) {
        const container = document.getElementById("fibonacci-sequence");
        container.innerHTML = '';

        const ul = document.createElement('ul');
        sequence.forEach((num) => {
            const li = document.createElement('li');
            li.textContent = num;
            ul.appendChild(li);
        });

        container.appendChild(ul);
    }

    // Generate and display the Fibonacci sequence up to the 20th term
    const sequence = generateFibonacci(20);
    displayFibonacci(sequence);
});
```

